<template>
  <main class="work-storage">
    <header><div><h1>工作资料管理</h1><p>查看原粮通报、原粮考勤和制曲上传资料，按需清理过期内容。</p></div><button :disabled="busy" @click="load">刷新</button></header>
    <section class="storage-summary" aria-label="选择功能"><button v-for="group in groups" :key="group.key" :class="{selected:featureKey===group.key}" :aria-pressed="featureKey===group.key" :disabled="busy" @click="selectFunction(group.key)"><span>{{group.label}}</span><strong>{{fileSize(group.bytes)}}</strong><small>{{group.count}} 份资料 · {{group.files}} 个文件</small></button></section>
    <section class="storage-controls"><label>资料类型<el-select v-if="selectedGroup.kinds.length>1" v-model="kind" :disabled="busy" placeholder="全部类型" aria-label="当前功能资料类型" @change="page=1;load()"><el-option label="全部类型" value=""/><el-option v-for="key in selectedGroup.kinds" :key="key" :label="typeLabels[key]" :value="key"/></el-select><span v-else class="single-kind">{{typeLabels[selectedGroup.kinds[0]]}}</span></label><label>最后更新早于<input v-model="cutoff" type="date" :max="yesterday" :disabled="busy" @change="page=1;load()"/></label><button class="batch-cleanup" :disabled="busy" @click="cleanupFunction">{{busy?'处理中…':'一键清理'}}</button><p>清理当前功能与资料类型下，所选日期之前、已过保留日期且未被引用的资料，包含所有分页。</p></section>
    <p v-if="error" class="storage-error" role="alert">{{error}}</p><p v-if="message" class="storage-message" role="status">{{message}}</p>
    <section class="storage-table-panel"><div class="storage-list-heading"><b>{{selectedGroup.label}}</b><span>{{total}} 份资料</span></div><div class="storage-table-scroll"><table><thead><tr><th>资料 / 类型</th><th>所属车间</th><th>文件 / 占用</th><th>最后更新</th><th>保留截止</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="`${item.kind}:${item.id}`"><td><b>{{item.title}}</b><small>{{typeLabels[item.kind]}} · #{{item.id}}</small></td><td>{{item.workshopCode==='raw_grain'?'原粮车间':'制曲车间'}}</td><td>{{fileSize(item.bytes)}}<small>{{item.fileCount}} 个文件</small></td><td>{{item.updatedAt}}</td><td><template v-if="['inspection','attendance'].includes(item.kind)"><button class="retention-button" :disabled="busy" @click="setRetention(item)">{{item.retentionUntil||'未设置'}}<el-icon><Edit /></el-icon></button></template><span v-else>按更新时间</span></td><td><span :class="item.eligible?'eligible':'protected'">{{item.eligible?'可清理':item.processingCount?'处理中，暂不清理':item.referenceCount?'仍被记录引用':item.retentionUntil&&item.retentionUntil>=today?'保留期内':'不在清理范围'}}</span></td><td><button class="delete-button" :disabled="busy||!item.eligible" @click="remove(item)">清理</button></td></tr></tbody></table></div><p v-if="!items.length" class="storage-empty">{{busy?'正在读取资料…':'没有此类资料。'}}</p><el-pagination v-if="total>30" v-model:current-page="page" :disabled="busy" :total="total" :page-size="30" layout="prev,pager,next,total" @current-change="load"/></section>
    <p class="storage-note">原粮通报、考勤导入会连同原文件和对应结果删除。制曲只清理截图或附件，保留工作文字和考评记录。清理会留下管理员操作日志，数据库空间供后续写入复用。</p>
    <details class="storage-audit" @toggle="loadAudit"><summary>最近清理记录</summary><ul><li v-for="entry in audit" :key="entry.id">{{entry.created_at}} · {{entry.title}} · 清理 {{fileSize(entry.released_bytes)}} · 操作人 #{{entry.actor_id}}</li></ul><p v-if="!audit.length">暂无清理记录。</p></details>
    <el-dialog v-model="retentionOpen" title="设置保留截止日期" width="min(440px, calc(100vw - 28px))" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy"><p>{{retentionItem?.title}}</p><label class="retention-field">保留到<input v-model="retentionDate" type="date" :disabled="busy"/></label><p>日期过后仍需管理员手动清理，不会自动删除。</p><template #footer><el-button :disabled="busy" @click="retentionOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveRetention">保存</el-button></template></el-dialog>
  </main>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {ElMessageBox} from 'element-plus'
import {Edit} from '@element-plus/icons-vue'
import {office} from '../api/attendance'
import {fileSize} from '../utils/attendance-display.mjs'
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),yesterday=new Date(Date.now()+8*3600000-86400000).toISOString().slice(0,10)
const cutoff=ref(new Date(Date.now()+8*3600000-90*86400000).toISOString().slice(0,10)),featureKey=ref('inspection'),kind=ref('inspection'),page=ref(1),items=ref([]),summary=ref([]),total=ref(0),busy=ref(false),error=ref(''),message=ref(''),audit=ref([])
const retentionOpen=ref(false),retentionItem=ref(null),retentionDate=ref('')
const typeLabels={inspection:'原粮检查通报',attendance:'原粮考勤导入',work_photo:'制曲工作截图',task_file:'制曲任务附件'}
const functionGroups=[{key:'inspection',label:'原粮检查通报',kinds:['inspection']},{key:'attendance',label:'原粮考勤核查',kinds:['attendance']},{key:'qu_making',label:'制曲履职考评',kinds:['work_photo','task_file']}]
const groups=computed(()=>functionGroups.map(g=>({...g,bytes:summary.value.filter(s=>g.kinds.includes(s.kind)).reduce((n,s)=>n+Number(s.bytes||0),0),count:summary.value.filter(s=>g.kinds.includes(s.kind)).reduce((n,s)=>n+Number(s.itemCount||0),0),files:summary.value.filter(s=>g.kinds.includes(s.kind)).reduce((n,s)=>n+Number(s.fileCount||0),0)})))
const selectedGroup=computed(()=>functionGroups.find(group=>group.key===featureKey.value))
const cleanupScope=()=>({function:featureKey.value,kind:kind.value,cutoff:cutoff.value})
async function readList(){const r=await office.get('/work-storage',{params:{...cleanupScope(),page:page.value}});items.value=r.data.items;summary.value=r.data.summary;total.value=r.data.total}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{await readList()}catch(e){error.value=e.response?.data?.msg||'资料读取失败'}finally{busy.value=false}}
async function selectFunction(key){if(busy.value||key===featureKey.value)return;featureKey.value=key;kind.value=selectedGroup.value.kinds.length===1?selectedGroup.value.kinds[0]:'';page.value=1;items.value=[];total.value=0;message.value='';await load()}
function deletionExplanation(functionKey){return functionKey==='qu_making'?'只删除图片或附件，工作文字和考评记录保留。':'原始文件、对应结果与相关备注将一并删除。'}
async function cleanupFunction(){
  if(busy.value)return
  busy.value=true;error.value='';message.value=''
  const scope=cleanupScope(),scopeLabel=`${selectedGroup.value.label}${scope.kind?` · ${typeLabels[scope.kind]}`:' · 全部资料类型'}`
  try{
    const r=await office.get('/work-storage/cleanup-preview',{params:scope}),preview=r.data
    if(!preview.itemCount){message.value='当前范围无符合条件资料。';return}
    if(!Array.isArray(preview.items)||preview.items.length!==preview.itemCount)throw new Error('清理预览资料不完整，请刷新后重试')
    try{await ElMessageBox.confirm(`将清理“${scopeLabel}”中最后更新早于 ${scope.cutoff}、符合保留与引用条件的 ${preview.itemCount} 份资料，共 ${fileSize(preview.totalBytes)}，包含所有分页。${deletionExplanation(scope.function)}删除后不可恢复。`,'一键清理资料',{type:'warning',confirmButtonText:'确认清理',cancelButtonText:'取消'})}catch{return}
    const result=await office.post('/work-storage/cleanup',{...scope,items:preview.items.map(item=>({kind:item.kind,id:item.id,revision:item.revision}))})
    message.value=`已清理 ${result.data.itemCount} 份资料，释放 ${fileSize(result.data.releasedBytes)} 数据内容。`
    page.value=1;await readList();await loadAudit()
  }catch(e){error.value=e.response?.data?.msg||e.message||'清理失败，请刷新后重试'}finally{busy.value=false}
}
async function remove(item){
  if(busy.value)return
  busy.value=true;error.value='';message.value=''
  try{try{await ElMessageBox.confirm(`清理“${item.title}”（${fileSize(item.bytes)}）？${deletionExplanation(featureKey.value)}删除后不可恢复。`,'清理过期资料',{type:'warning',confirmButtonText:'确认清理',cancelButtonText:'取消'})}catch{return}const r=await office.delete(`/work-storage/${item.kind}/${item.id}`,{data:{cutoff:cutoff.value,revision:item.revision}});message.value=`已清理 ${fileSize(r.data.releasedBytes)} 数据内容。`;if(items.value.length===1&&page.value>1)page.value--;await readList();await loadAudit()}catch(e){error.value=e.response?.data?.msg||'清理失败，请刷新后重试'}finally{busy.value=false}
}
function setRetention(item){if(busy.value)return;retentionItem.value=item;retentionDate.value=item.retentionUntil||'';retentionOpen.value=true}
async function saveRetention(){if(busy.value)return;busy.value=true;error.value='';try{await office.patch(`/work-storage/${retentionItem.value.kind}/${retentionItem.value.id}/retention`,{retentionUntil:retentionDate.value||null,revision:retentionItem.value.revision});retentionOpen.value=false;await readList()}catch(e){error.value=e.response?.data?.msg||'保留日期保存失败，请刷新后重试'}finally{busy.value=false}}
async function loadAudit(event){if(event&&!event.target.open)return;try{const r=await office.get('/work-storage/audit');audit.value=r.data}catch{error.value='清理日志读取失败'}}
onMounted(load)
</script>
<style scoped>
.work-storage{max-width:1440px;margin:auto;color:#183047;display:grid;gap:18px;font-size:14px}.work-storage header{display:flex;justify-content:space-between;align-items:center;gap:16px}.work-storage h1{font-size:26px;margin:0 0 8px}.work-storage p{color:#607487;font-size:13px;line-height:1.8;margin:0}.work-storage button{display:inline-flex;align-items:center;gap:6px;min-height:36px;padding:8px 14px;border:1px solid #dee5ed;border-radius:7px;background:white;color:#5b5cab;font:inherit;font-size:13px;cursor:pointer}.work-storage button:disabled{opacity:.4;cursor:default}.storage-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.storage-summary>div{background:white;border:1px solid #dee5ed;border-radius:10px;padding:20px;display:grid;gap:14px}.storage-summary strong{font-size:27px;color:#45468b}.storage-summary small{font-size:12px;color:#8492a6}.storage-controls{display:flex;gap:18px;align-items:end;flex-wrap:wrap}.storage-controls label{display:grid;gap:8px}.storage-controls .el-select{width:220px}.storage-controls input,.retention-field input{padding:8px 12px;border:1px solid #dee5ed;border-radius:6px;background:white;color:#183047;font:inherit;min-height:38px}.storage-controls p{flex:1;padding-bottom:5px}.storage-table-panel{background:white;border:1px solid #dee5ed;border-radius:10px;padding:18px}.storage-table-scroll{overflow:auto}.work-storage table{width:100%;border-collapse:collapse;min-width:1050px;text-align:left;font-size:13px}.work-storage th{background:#f6f7fa;color:#607487;padding:13px;font-weight:600;white-space:nowrap}.work-storage td{padding:16px 13px;border-bottom:1px solid #e8ecf1;vertical-align:middle;line-height:1.5}.work-storage td:first-child{max-width:350px;overflow-wrap:anywhere}.work-storage td small{display:block;margin-top:6px;color:#8492a6;font-size:12px}.work-storage .retention-button{border:0;background:transparent;padding:0;min-height:28px}.work-storage .delete-button{color:#bd2438;border-color:#eccbd0}.eligible{color:#258161;background:#eaf7f3;padding:4px 7px;border-radius:5px;white-space:nowrap}.protected{color:#8492a6;white-space:nowrap}.work-storage .storage-error{color:#bd2438;background:#fff1f2;padding:12px;border-radius:7px}.work-storage .storage-message{color:#258161;background:#eaf7f3;padding:12px;border-radius:7px}.storage-table-panel .el-pagination{justify-content:flex-end;margin-top:18px}.work-storage .storage-empty{text-align:center;padding:40px}.storage-note{padding:0 2px}.storage-audit{background:white;border:1px solid #dee5ed;padding:16px;border-radius:10px;font-size:13px;color:#607487}.storage-audit summary{cursor:pointer;color:#183047}.storage-audit li{line-height:1.8;margin-top:8px}.retention-field{display:grid;gap:8px;margin:18px 0}.work-storage button:focus-visible,.work-storage input:focus-visible{outline:2px solid #5b5cab;outline-offset:2px}@media(max-width:650px){.storage-summary{gap:8px}.storage-summary>div{padding:13px;gap:10px}.storage-summary strong{font-size:19px}.storage-summary span{font-size:13px}.work-storage h1{font-size:22px}.storage-controls label{width:100%}.storage-controls .el-select{width:100%}.storage-controls p{flex-basis:100%}.storage-table-panel{padding:10px}}
.storage-summary>button{background:white;border:1px solid #dee5ed;border-radius:10px;padding:20px;display:grid;gap:14px;text-align:left;min-width:0;align-items:start;justify-items:start;transition:border-color .15s,background .15s}.storage-summary>button.selected{border-color:#5b5cab;background:#f2f2fc;box-shadow:inset 0 0 0 1px #5b5cab}.storage-summary>button>span{font-weight:600;color:#35465b}.storage-summary>button strong{font-size:27px;color:#45468b}.storage-summary>button small{font-size:12px;color:#8492a6}.single-kind{display:flex;align-items:center;height:40px;width:220px;padding:8px 12px;border:1px solid #dee5ed;border-radius:6px;background:#f8fafc;color:#607487;font-size:13px}.storage-controls input{height:40px;box-sizing:border-box}.storage-controls :deep(.el-select__wrapper){min-height:40px}.work-storage .batch-cleanup{height:40px;min-height:40px;background:#5b5cab;border-color:#5b5cab;color:white}.storage-list-heading{display:flex;align-items:center;gap:12px;margin:0 0 14px;color:#35465b}.storage-list-heading span{color:#8492a6;font-size:12px}.storage-controls p{min-width:260px}.work-storage button:focus-visible{outline:2px solid #5b5cab;outline-offset:3px}
@media(max-width:650px){.storage-summary>button{padding:13px;gap:10px}.storage-summary>button strong{font-size:19px}.storage-summary>button>span{font-size:12px}.single-kind{width:100%;box-sizing:border-box}.storage-controls .batch-cleanup{width:100%;justify-content:center}.storage-controls p{min-width:0}}
@media(max-width:420px){.storage-summary{grid-template-columns:1fr}.storage-summary>button{grid-template-columns:minmax(0,1fr) auto;gap:6px 12px;align-items:center}.storage-summary>button strong{grid-row:1/3;grid-column:2}.storage-summary>button small{grid-column:1;font-size:11px}}
</style>
